using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveMappingChecks
    {
        [Serializable]sealed class CheckResult{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string scope="Editor native Book, Hand, nearby crystal/verdict/property buttons, Undo and Check controls. Seed fixtures cover both classification outcomes and property combinations. Deadlines are aged; physical Android is separate.";public List<CheckResult> checks=new List<CheckResult>();public List<string> errors=new List<string>();}
        static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveMappingPresentation art;static ArchiveMappingUI ui;static bool active,oldHunting;static double next;static GameObject restriction;
        static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[7];
        public static int RelationSeed(ArchiveTopicCatalog c)=>Enumerable.Range(310000,4096).First(seed=>ArchiveTopicQuestions.Build(c,7,3,seed).mapping.correctClassificationIndex==2&&(int)ArchiveTopicQuestions.Build(c,7,4,seed).mapping.correctProperties==4);
        public static int FunctionSeed(ArchiveTopicCatalog c)=>Enumerable.Range(320000,4096).First(seed=>ArchiveTopicQuestions.Build(c,7,3,seed).mapping.correctClassificationIndex==0&&(int)ArchiveTopicQuestions.Build(c,7,4,seed).mapping.correctProperties==14);
        public static void Begin(){if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Use offline Play Mode.");session=ArchiveTopicSession.Current;station=session.stations[7];art=station.GetComponent<ArchiveMappingPresentation>();ui=ArchiveTopicUI.Current.GetComponent<ArchiveMappingUI>();report=new Report();oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;stack.Clear();stack.Push(Flow());active=true;next=0;Status="Starting";EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new Exception("Play stopped.");if(stack.Count==0){Finish(true);return;}var flow=stack.Peek();if(!flow.MoveNext()){stack.Pop();return;}if(flow.Current is IEnumerator nested)stack.Push(nested);else next=EditorApplication.timeSinceStartup+(flow.Current is float delay?delay:0);}catch(Exception ex){report.errors.Add(Status+": "+ex);Finish(false);}}
        static void Check(bool passed,string name){report.checks.Add(new CheckResult{name=name,passed=passed});if(!passed)throw new Exception(name);}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static IEnumerator Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();yield return .25f;ArchiveTopicUI.Current.Close();}
        static IEnumerator Input(int index,bool button=false){Move(station.InputPosition(index));if(button){ArchiveTopicUI.Current.Open(station);yield return .1f;Check(ui.DomainButtons[index].interactable,"Nearby Domain UI button is enabled");ui.DomainButtons[index].onClick.Invoke();ArchiveTopicUI.Current.Close();}else station.points.First(p=>p.role==ArchivePointRole.Input&&p.index==index).Interact();yield return .06f;var actor=session.State.actors.First(a=>a.actor==-1);Check(actor.mappingInput==index&&actor.mappingRound==State.round,"Hand selects Domain "+index+" for this actor and round");}
        static IEnumerator Output(int index,bool button=false){int input=session.State.actors.First(a=>a.actor==-1).mappingInput;Move(station.OutputPosition(index));if(button){ArchiveTopicUI.Current.Open(station);yield return .1f;Check(ui.OutputButtons[index].interactable,"Nearby Codomain UI button is enabled");ui.OutputButtons[index].onClick.Invoke();ArchiveTopicUI.Current.Close();}else station.points.First(p=>p.role==ArchivePointRole.Output&&p.index==index).Interact();yield return .06f;Check(State.links.Contains(input*100+index),"Directed laser connects the chosen input and output");}
        static IEnumerator Connect(int link){yield return Input(link/100);yield return Output(link%100);}
        static IEnumerator Arrange(){var q=session.Question(7);foreach(int link in ArchiveTopicChecks.Solution(q).links.Except(State.links).ToArray())yield return Connect(link);}
        static IEnumerator Select(int value,bool property=false,bool button=false){bool was=(State.flags&value)!=0;int index=property?Array.IndexOf(new[]{2,4,8},value):value;Move(ArchiveMappingPresentation.AnswerPosition(index));if(button){ArchiveTopicUI.Current.Open(station);yield return .1f;var target=property?ui.PropertyButtons[index]:ui.ClassificationButtons[index];Check(target.interactable,"Nearby verdict/property UI button is enabled");target.onClick.Invoke();ArchiveTopicUI.Current.Close();}else station.points.First(p=>p.role==ArchivePointRole.Select&&p.index==value).Interact();yield return .06f;Check(property?((State.flags&value)!=0)!=was:State.selection==value,"Native seal records "+(property?"property "+value:"classification "+value));}
        static IEnumerator Properties(int wanted){foreach(int flag in new[]{2,4,8})if(((State.flags^wanted)&flag)!=0)yield return Select(flag,true,true);}
        static IEnumerator Submit(){Move(Vector3.zero);ui.CheckButton.onClick.Invoke();yield return .18f;}
        static IEnumerator Undo(){Move(station.OutputPosition(0));ArchiveTopicUI.Current.Open(station);yield return .1f;Check(ui.UndoButton.interactable,"Undo is enabled beside Codomain when an editable laser exists");ui.UndoButton.onClick.Invoke();yield return .08f;ArchiveTopicUI.Current.Close();}
        static IEnumerator Preview(string name,bool reader){Move(new Vector3(0,0,6.0f));Player.LocalInstance.transform.rotation=station.transform.rotation*Quaternion.Euler(0,180,0);var look=Player.LocalInstance.GetComponentInChildren<CameraTargetController>();if(look!=null)look.SetViewAngles(34,station.transform.eulerAngles.y+180);if(reader)ArchiveTopicUI.Current.Open(station);else ArchiveTopicUI.Current.Close();yield return .35f;Directory.CreateDirectory("Temp/T8Polish");ScreenCapture.CaptureScreenshot("Temp/T8Polish/"+name+".png");yield return .25f;}
        static IEnumerator Flow(){
            Status="Book, range and incorrect links";session.Initialize(RelationSeed(session.catalog));Move(Vector3.zero);ArchiveTopicUI.Current.Close();yield return .65f;var book=station.GetComponentInChildren<ArchiveAnimatedBook>();Check(book.OpenAmount<.01f&&!State.timerRunning&&session.TimerRemaining(State)==600,"Arrival leaves the current solo ten-minute clock unstarted");ArchiveTopicUI.Current.Open(station);yield return .1f;Check(!State.timerRunning&&!Player.LocalInstance.IsMovementLocked,"Reader preview leaves movement and the unstarted clock alone");ArchiveTopicUI.Current.Close();yield return Book();yield return .7f;Check(State.phase==1&&State.timerRunning&&State.timerLimit==600&&book.OpenAmount>.98f,"Native Book starts the shared ten-minute mapping clock");Check(art.PortRoots.Length==8&&station.points.Count(p=>p.role==ArchivePointRole.Input)==4&&station.points.Count(p=>p.role==ArchivePointRole.Output)==4,"Four Domain and four Codomain crystals use native Hand controls");Check(!ui.CheckButton.interactable&&State.links.Count==0,"Empty mapping cannot be submitted through the test UI");var q=session.Question(7);double deadline=State.timerDeadline;ArchiveTopicUI.Current.Open(station);yield return .1f;Check(ui.ReadingText.text.Contains(q.prompt),"Reader preserves the complete current solo instruction");ArchiveTopicUI.Current.Close();
            Move(station.OutputPosition(0));int revision=State.revision;station.points.First(p=>p.role==ArchivePointRole.Output&&p.index==0).Interact();yield return .1f;Check(State.revision==revision&&State.links.Count==0,"Codomain cannot connect before this actor selects an input");Move(Vector3.zero);ui.DomainButtons[0].onClick.Invoke();yield return .1f;Check(State.revision==revision,"An out-of-reach Domain button cannot forge an input selection");
            var solution=ArchiveTopicChecks.Solution(q).links;foreach(int link in solution.Where(link=>link/100!=0))yield return Connect(link);yield return Input(0,true);int expected=solution.First(link=>link/100==0)%100,wrong=(expected+1)%4;yield return Output(wrong,true);Check(art.BeamCount==4&&ArchiveMappingPresentation.RangeText(q,State).Contains(q.outputLabels[wrong]),"Directed lasers and actual range reflect the current shared relation");var links=State.links.ToArray();var ids=station.workRoot.GetComponentsInChildren<LineRenderer>().Select(r=>r.GetInstanceID()).ToArray();Move(station.InputPosition(0));revision=State.revision;session.Request(7,ArchiveAction.Undo);yield return .1f;Check(State.revision==revision&&State.links.SequenceEqual(links),"Undo is rejected away from the Codomain crystals");yield return Preview("T8_Conduit",false);yield return Preview("T8_Reader",true);ArchiveTopicUI.Current.Close();yield return Submit();Check(State.round==0&&session.State.mistakes.Count==1&&State.lastAnswerActor==-1&&Math.Abs(State.timerDeadline-(deadline-10))<.000001,"Incorrect relation records its submitting actor once and deducts ten seconds");Check(State.links.SequenceEqual(links)&&ids.SequenceEqual(station.workRoot.GetComponentsInChildren<LineRenderer>().Select(r=>r.GetInstanceID())),"Wrong submission retains every connection and physical laser object");var tint=new MaterialPropertyBlock();station.workRoot.GetComponentInChildren<LineRenderer>().GetPropertyBlock(tint);Check(tint.GetColor("_BaseColor").r>tint.GetColor("_BaseColor").g,"Incorrect submission flashes the existing laser red");revision=State.revision;yield return Submit();Check(State.revision==revision&&session.State.mistakes.Count==1,"Rapid duplicate Check cannot charge another penalty");
            State.timerDeadline=ArchiveTopicSession.TimerClock+3;yield return 1.6f;yield return Submit();Check(State.phase==0&&State.timerExpired&&session.State.mistakes.Count==2&&State.links.SequenceEqual(links),"A penalty exhausting time keeps the relation and charges no extra timeout mistake");yield return Book();Check(State.timerAttempt==2&&session.TimerRemaining(State)>599&&State.links.SequenceEqual(links)&&session.State.actors.All(a=>a.mappingInput<0),"Book retry preserves the relation and resets pending input selection");yield return Undo();Check(State.links.Count==3&&!State.links.Contains(wrong),"Undo removes the last editable team laser");yield return Input(0);yield return Output(expected);yield return 1.6f;yield return Submit();Check(State.round==1&&State.phase==0&&!State.timerRunning&&session.ActiveTopic==7&&!session.CanStartTopic(0),"Correct relation reaches a paused Book gate while reserving the team topic");float saved=session.TimerRemaining(State);State.timerDeadline=ArchiveTopicSession.TimerClock-1;int before=session.State.mistakes.Count;yield return .3f;Check(session.TimerRemaining(State)==saved&&!State.timerExpired&&session.State.mistakes.Count==before,"Solved Book gate pauses the remaining solo-style clock without a phantom timeout");
            Status="Arbitrary relation and active timeout";yield return Book();Check(session.TimerRemaining(State)<=saved&&session.TimerRemaining(State)>saved-1&&State.links.Count==0,"Next Book resumes the saved remaining time and clears only the solved diagram");q=session.Question(7);var pairs=q.mapping.requiredPairs;string repeated=pairs.GroupBy(p=>p.domain).First(g=>g.Count()>1).Key;foreach(var group in pairs.GroupBy(p=>p.domain)){yield return Input(Array.IndexOf(q.inputLabels,group.Key));foreach(var pair in group)yield return Output(Array.IndexOf(q.outputLabels,pair.codomain));}Check(State.links.Count==5&&!MappingRuleEvaluator.IsFunction(ArchiveTopicQuestions.Pairs(q,State.links),q.inputLabels),"Arbitrary relation accepts two different outputs from one input");int duplicate=State.links.Last();yield return Input(duplicate/100);Move(station.OutputPosition(duplicate%100));revision=State.revision;session.Request(7,ArchiveAction.Connect,duplicate/100,duplicate%100);yield return .1f;Check(State.revision==revision&&State.links.Count==5,"Duplicate pair is rejected without charging a mistake");links=State.links.ToArray();before=session.State.mistakes.Count;State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.phase==0&&State.timerExpired&&State.round==1&&State.links.SequenceEqual(links)&&session.State.mistakes.Count==before+1,"Natural timeout keeps the solved first challenge and all current relation pairs");yield return Book();Check(State.links.SequenceEqual(links),"Timeout retry resumes the exact unfinished five-laser relation");yield return Submit();Check(State.round==2&&State.phase==0,"Complete ordered-pair relation advances the shared challenge");
            Status="Fixed bijection and capture";yield return Book();q=session.Question(7);int fixedLink=State.links.Single();Check(q.mapping.initialPairsLocked&&State.links.Count==1&&art.BeamCount==1&&ArchiveMappingPresentation.Fixed(fixedLink,q),"Bijection begins with exactly one fixed amber connection");Move(station.OutputPosition(0));revision=State.revision;session.Request(7,ArchiveAction.Undo);yield return .1f;Check(State.revision==revision&&State.links.SequenceEqual(new[]{fixedLink}),"Fixed initial laser cannot be undone");yield return Input(0);restriction=new GameObject("T8 capture fixture");Player.LocalInstance.AcquireMovementLock(restriction,"T8 captured",Player.LocalInstance.transform.position,100);yield return .3f;Check(!session.CanAct(-1)&&session.State.actors.First(a=>a.actor==-1).mappingInput<0&&!ui.IsObjectiveVisible,"Capture clears the pending input and hides local mapping controls");revision=State.revision;session.Request(7,ArchiveAction.Connect,0,0);yield return .1f;Check(State.revision==revision&&State.links.Count==1,"Captured player cannot add a mapping laser");Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);restriction=null;yield return Arrange();int extra=Enumerable.Range(0,16).Select(i=>(i/4)*100+i%4).First(link=>!State.links.Contains(link));yield return Connect(extra);deadline=State.timerDeadline;yield return Submit();Check(State.round==2&&State.links.Count==5&&Math.Abs(State.timerDeadline-(deadline-10))<.000001,"Extra output fails the required bijection while keeping the fixed connection");yield return Undo();Check(State.links.Count==4&&State.links.Contains(fixedLink),"Undo removes the extra output and retains the fixed bijection clue");yield return 1.6f;yield return Submit();Check(State.round==3&&State.phase==0,"Completed constrained bijection advances to classification");
            Status="Three verdicts and property toggles";yield return Book();q=session.Question(7);Check(q.mapping.correctClassificationIndex==2&&art.AnswerRoots.Length==3&&art.AnswerRoots.Select(t=>t.GetComponentInChildren<TMPro.TMP_Text>().text).SequenceEqual(ArchiveMappingPresentation.ClassificationNames),"Three verdicts match updated solo order; Relation Only index two is available");Check(station.points.All(p=>p.role!=ArchivePointRole.Input&&p.role!=ArchivePointRole.Output),"Preset classification diagram has no editable crystal points");links=State.links.ToArray();Move(station.OutputPosition(0));revision=State.revision;session.Request(7,ArchiveAction.Connect,0,0);session.Request(7,ArchiveAction.Undo);yield return .1f;Check(State.revision==revision&&State.links.SequenceEqual(links),"Classification preset cannot be edited or undone");yield return Preview("T8_Verdicts",false);yield return Select(1,false,true);yield return Submit();Check(State.round==3&&State.selection==1&&State.links.SequenceEqual(links),"Distractor verdict retains the diagram and chosen answer for correction");yield return Select(2);yield return 1.6f;yield return Submit();Check(State.round==4&&State.reveal.Contains("Relation Only"),"Previously missing Relation Only answer completes classification");
            yield return Book();q=session.Question(7);Check((int)q.mapping.correctProperties==4&&art.AnswerRoots.Select(t=>t.GetComponentInChildren<TMPro.TMP_Text>().text).SequenceEqual(ArchiveMappingPresentation.PropertyNames),"Three property seals reuse solo's surjective-relation question");yield return Properties(14);yield return Submit();Check(State.round==4&&State.flags==14,"Extra selected properties are rejected and remain available for correction");links=State.links.ToArray();State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.flags==14&&State.links.SequenceEqual(links),"Property timeout retains the selected flags and preset arrows");yield return Book();Check(State.flags==14&&State.links.SequenceEqual(links),"Property retry restores the exact unfinished choices");yield return Properties(4);yield return 1.6f;yield return Submit();Check(State.round==5&&State.phase==2&&!State.timerRunning&&session.ActiveTopic==-1,"Five mapping challenges complete for the team and release the next topic");saved=session.TimerRemaining(State);yield return .2f;Check(session.TimerRemaining(State)==saved,"Completed mapping clock remains frozen");
            Status="Function and bijection answer fixtures";session.Initialize(FunctionSeed(session.catalog));State.round=3;yield return .2f;yield return Book();q=session.Question(7);Check(q.mapping.correctClassificationIndex==0,"Second source fixture is a genuine function");yield return Select(0,false,true);yield return Submit();Check(State.round==4,"Function Only index zero completes the second classification fixture");yield return Book();Check((int)session.Question(7).mapping.correctProperties==14,"Second source property fixture is bijective");yield return Properties(14);yield return Preview("T8_Properties",false);yield return Submit();Check(State.phase==2&&State.reveal.Contains("Injective")&&State.reveal.Contains("Surjective")&&State.reveal.Contains("Bijective"),"All three properties are required and published for a bijection");
            Check(session.State.stations.Where(s=>s.topic!=7).All(s=>s.round==0&&s.timerAttempt==0),"T8 preserves all other topic progress and clocks");Check(!Player.LocalInstance.IsMovementLocked&&Time.timeScale==1&&report.errors.Count==0,"Normal player controls remain available and no runtime errors occurred");Status="Passed";
        }
        public static string ValidateVariants(){
            var catalog=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var source=AssetDatabase.LoadAssetAtPath<MappingChallengeCatalog>("Assets/Resources/FunctionsRelationsChallenges.asset");var checks=new List<CheckResult>();var failures=new List<string>();int variants=0;
            Action<bool,string> test=(ok,name)=>{checks.Add(new CheckResult{name=name,passed=ok});if(!ok)failures.Add(name);};
            try{test(catalog.mappings==source,"Archive uses the actual updated solo catalog without a duplicate bank");for(int group=0;group<5;group++)for(int entry=0;entry<source.ChallengeGroups[group].variants.Count;entry++){
                int round=group;var data=source.GetVariant(group,entry);int seed=Enumerable.Range(1,4096).First(s=>ReferenceEquals(ArchiveTopicQuestions.Build(catalog,7,round,s).mapping,data));var q=ArchiveTopicQuestions.Build(catalog,7,group,seed);var good=ArchiveTopicChecks.Solution(q);string name="Challenge "+(group+1)+" / variant "+(entry+1);variants++;
                test(q.prompt==data.instruction&&q.inputLabels.SequenceEqual(data.domain)&&q.outputLabels.SequenceEqual(data.codomain),name+" preserves solo instruction and physical endpoint order");test(ArchiveTopicQuestions.Validate(q,good,out _),name+" accepts the original complete answer");test(MappingRuleEvaluator.HasValidEndpoints(ArchiveTopicQuestions.Pairs(q,good.links),q.inputLabels,q.outputLabels),name+" has valid distinct endpoint pairs");var bad=ArchiveTopicChecks.Solution(q);if(group<3)bad.links.RemoveAt(bad.links.Count-1);else if(group==3)bad.selection=(data.correctClassificationIndex+1)%3;else bad.flags^=2;test(!ArchiveTopicQuestions.Validate(q,bad,out _),name+" rejects an incomplete or incorrect answer");bad=ArchiveTopicChecks.Solution(q);bad.links.Add(9999);test(!ArchiveTopicQuestions.Validate(q,bad,out _),name+" rejects malformed link IDs without throwing");bad=ArchiveTopicChecks.Solution(q);bad.links.Add(bad.links[0]);test(!ArchiveTopicQuestions.Validate(q,bad,out _),name+" rejects duplicate pairs");
                if(group==1)test(data.requiredPairs.GroupBy(p=>p.domain).Any(g=>g.Count()>1)&&!MappingRuleEvaluator.IsFunction(data.requiredPairs,data.domain),name+" retains a genuine multi-output relation");if(group==2)test(data.initialPairs.Count==1&&data.initialPairsLocked&&data.requiredPairs.Count==4&&MappingRuleEvaluator.IsBijective(data.requiredPairs,data.domain,data.codomain),name+" preserves its locked bijection clue");if(group==3)test(data.correctClassificationIndex==(MappingRuleEvaluator.IsFunction(data.initialPairs,data.domain)?0:2),name+" matches the current three-pedestal classification");if(group==4)test((int)data.correctProperties==4||(int)data.correctProperties==14,name+" retains the source surjective/bijective outcomes");
            }var font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");test(font.HasCharacter('→',true,false),"Existing reading font renders mapping arrows");}catch(Exception ex){failures.Add(ex.ToString());}
            var result=new{passed=failures.Count==0,sourceVariants=variants,checks=checks,failures=failures};Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T8MappingVariants.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return(result.passed?"Passed":"Failed")+": "+variants+" source variants / "+checks.Count+" checks";
        }
        static void Finish(bool ok){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(restriction!=null){Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);}if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=ok&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T8PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T8 Mapping Conduit: "+Status+" / "+report.checks.Count);}
    }
